  "settings.game.cacheRollingBranchesHint": "Conserve chaque version develop et bêta jouée, pour que leurs replays restent lisibles.",
  "settings.game.experimentalBadge": "Expérimental",
  "settings.game.cacheRollingBranchesDocTitle": "Fonctionnement de la mise en cache des branches de développement et des replays",
  "settings.game.cacheRollingBranchesDocOverview": "Les branches évolutives comme FAF Develop et FAF Beta n'ont pas de numéros de version permanents sur le serveur. Lorsque de nouveaux commits sont publiés, les anciens fichiers sont écrasés, ce qui désynchronise les anciens replays.",
  "settings.game.cacheRollingBranchesDocHowTitle": "Instantanés de versions",
  "settings.game.cacheRollingBranchesDocHowDesc": "Lorsqu'il est activé, chaque build unique est identifié par son SHA de commit Git et sa somme de contrôle, puis indexé dans un manifeste local.",
  "settings.game.cacheRollingBranchesDocReplayTitle": "Modifications des fichiers de replay",
  "settings.game.cacheRollingBranchesDocReplayDesc": "Les fichiers .fafreplay enregistrés localement intègrent les champs git_sha, git_short_sha et build_signature dans leur en-tête JSON. Cela permet au client de restaurer la version exacte lors du visionnage, tout en restant compatible avec les autres clients FAF.",
  "settings.game.cacheRollingBranchesDocStorageTitle": "Efficacité du stockage",
  "settings.game.cacheRollingBranchesDocStorageDesc": "Les fichiers sont liés par liens matériels sans occuper d'espace disque supplémentaire. Vous pouvez les consulter ou les supprimer dans la liste ci-dessous.",
